grid=[[8]*14 for _ in range(18)]
# template non-background pixels
obj={(2,11):1,(2,12):7,(3,9):1,(3,10):0,(3,11):0,(3,12):1,(4,8):7,(4,9):0,(4,10):1,(4,11):1,(4,12):7}
for (r,c),v in obj.items(): grid[r][c]=v
markers=[(2,4),(7,3),(9,8),(11,2),(16,3),(16,9)]
for p in markers:
    grid[p[0]][p[1]]=3
for ar,ac in markers:
    for (r,c),v in obj.items():
        rr=ar+(r-3); cc=ac+(c-10)
        if 0<=rr<len(grid) and 0<=cc<len(grid[0]): grid[rr][cc]=v
print('\n'.join(' '.join(map(str,row)) for row in grid))
